-- Pulse Wireless Earbuds
do $$
declare p_pulse_wireless_earbuds uuid; v_color uuid; v_variant uuid; v_asset uuid; v_model uuid;
begin
  if exists (select 1 from public.products where slug = 'pulse-wireless-earbuds') then return; end if;
  values ('Pulse Wireless Earbuds', 'pulse-wireless-earbuds', 'STM-PWE', (select id from public.categories where slug = 'audio'), 'unisex', 'Compact true-wireless earbuds with a pocketable charging case and touch controls.', 'Pulse earbuds sit light in the ear and pair quickly with your phone. The slim case tops them up on the go.

- Three sizes of silicone ear tips in the box
- Touch controls for music and calls
- USB-C charging case
- Up to 6 hours per charge, 24 hours with the case (varies with use)', 499900, 299900, 'draft', now() - interval '33 days', true, false, true, true, array['earbuds', 'wireless', 'audio', 'bluetooth']::text[], 'Option', v_model, null, 'Pulse Wireless Earbuds — Graphite', 'Compact true-wireless earbuds with a pocketable charging case and touch controls.')
  returning id into p_pulse_wireless_earbuds;
  update public.products set status = 'published' where id = p_pulse_wireless_earbuds;
end $$;

